window.dataLayer = window.dataLayer || [];
  function gtag(){dataLayer.push(arguments);}

  gtag('consent', 'default', {
    analytics_storage: 'denied',
    ad_storage: 'denied',
    ad_user_data: 'denied',
    ad_personalization: 'denied',
    functionality_storage: 'denied',
    security_storage: 'granted',
    region: ['BE', 'BG', 'CZ', 'DK', 'DE', 'EE', 'IE', 'EL', 'ES', 'FR', 'HR', 'IT', 'CY', 'LV', 'LT', 'LU', 'HU', 'MT', 'NL', 'AT', 'PL', 'PT', 'RO', 'SI', 'SK', 'FI', 'SE', 'IS', 'LI', 'NO', 'CH', 'GB'],
    wait_for_update: 500
  });

  gtag('consent', 'default', {
    analytics_storage: 'granted',
    ad_storage: 'granted',
    ad_user_data: 'granted',
    ad_personalization: 'granted',
    functionality_storage: 'granted',
    security_storage: 'granted',
    wait_for_update: 500
  });

  // version & expire check
  try {
    var rawConsent = localStorage.getItem('cf_cookie_consent');
    if (rawConsent) {
      var consentData = JSON.parse(rawConsent);
      var expireMs = 365 * 24 * 60 * 60 * 1000;
      if (consentData.v === '1.0' && (Date.now() - consentData.ts < expireMs)) {
        gtag('consent', 'update', {
          analytics_storage: consentData.analytics ? 'granted' : 'denied',
          ad_storage: consentData.marketing ? 'granted' : 'denied',
          ad_user_data: consentData.marketing ? 'granted' : 'denied',
          ad_personalization: consentData.marketing ? 'granted' : 'denied',
          functionality_storage: consentData.preferences ? 'granted' : 'denied'
        });
      }
    }
  } catch(e) {}




  gtag('js', new Date()); gtag('config', 'G-YZFL2QW17X');




